cards.label:
[[[
  const people = [
    {
      entity: 'person.nunosantos',
      name: 'Nuno',
      initials: 'N',
      color: '#00CED1'
    },
    {
      entity: 'person.mariana',
      name: 'Mariana',
      initials: 'M',
      color: '#EE82EE'
    }
  ];

  const home = people.filter(p => states[p.entity]?.state === 'home');
  const occupied = home.length > 0;

  const residents = home.map(p => `
    <span style="
      display:inline-flex;
      align-items:center;
      gap:7px;
      padding:5px 10px 5px 6px;
      border-radius:20px;
      background:${p.color}18;
      color:${p.color};
      font-size:25px;
      font-weight:500;">
      <span style="
        width:22px;
        height:22px;
        display:inline-flex;
        align-items:center;
        justify-content:center;
        border-radius:50%;
        background:${p.color};
        color:#111;
        font-size:16px;
        font-weight:800;">
        ${p.initials}
      </span>
      ${p.name}
    </span>
  `).join('');

  // Mantém a Diana associada à presença da Mariana.
  const diana = states['person.mariana']?.state === 'home'
    ? `<span style="
        display:inline-flex;
        align-items:center;
        gap:7px;
        padding:5px 10px 5px 6px;
        border-radius:20px;
        background:#EE82EE18;
        color:#EE82EE;
        font-size:25px;
        font-weight:600;">
        <span style="
          width:22px;
          height:22px;
          display:inline-flex;
          align-items:center;
          justify-content:center;
          border-radius:50%;
          background:#EE82EE;
          color:#111;
          font-size:16px;
          font-weight:800;">
          D
        </span>
        Diana
      </span>`
    : '';

  return `
    <div style="display:flex; align-items:center; justify-content:center; width:100%; gap:52px;">
      <div style="display:flex; align-items:center; gap:22px;">
        <ha-icon
          icon="${occupied ? 'mdi:home-account' : 'mdi:home-outline'}"
          style="--mdc-icon-size:38px; color:${occupied ? '#58D68D' : '#9BA4B5'};">
        </ha-icon>
        <div style="display:flex; flex-direction:column; align-items:flex-start;">
        <span style="font-size:23px; font-weight:650; color:white;">
          ${occupied ? 'Bem vindo' : 'Casa vazia'}
        </span>
        <span style="font-size:18px; opacity:0.55; color:white;">
          ${occupied ? 'Quem está em casa' : 'A casa está tranquila'}
        </span>
        </div>
      </div>
      <div style="display:flex; flex-wrap:wrap; justify-content:center; gap:10px;">
        ${occupied ? residents + diana : '<span style="font-size:13px; opacity:0.55;">Tudo tranquilo</span>'}
      </div>
    </div>
  `;
]]]

