    if (!Array.isArray(root?.attributes?.entity_id)) return '—';

    const seen = new Set();
    let count = 0;

    const visit = (id) => {
      if (seen.has(id)) return;
      seen.add(id);

      const s = hass.states[id];
      const members = s?.attributes?.entity_id;

      if (Array.isArray(members)) {
        members.forEach(visit);
      } else if (id.startsWith('light.') && s?.state === 'on') {
        count++;
      }
    };

    visit('light.grupoluzessala');
    return count;
